  `lock_version` int unsigned NOT NULL DEFAULT '1' COMMENT '乐观锁版本',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间 UTC',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间 UTC',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_interview_sessions_application_request` (`application_id`,`client_request_id`),
  KEY `idx_interview_sessions_application_time` (`application_id`,`start_at`,`end_at`,`id`),
  KEY `idx_interview_sessions_application_status_time` (`application_id`,`status`,`start_at`,`id`),
  KEY `idx_interview_sessions_application_completed` (`application_id`,`status`,`completed_at` DESC,`id` DESC),
  CONSTRAINT `fk_interview_sessions_application` FOREIGN KEY (`application_id`) REFERENCES `job_applications` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_interview_sessions_lifecycle` CHECK ((((`status` = _utf8mb4'scheduled') and (`completed_at` is null) and (`cancelled_at` is null)) or ((`status` = _utf8mb4'completed') and (`completed_at` is not null) and (`cancelled_at` is null)) or ((`status` = _utf8mb4'cancelled') and (`completed_at` is null) and (`cancelled_at` is not null) and (`round_result` = _utf8mb4'pending')))),
  CONSTRAINT `ck_interview_sessions_lock_version` CHECK ((`lock_version` >= 1)),
  CONSTRAINT `ck_interview_sessions_mode` CHECK ((`mode` in (_utf8mb4'video',_utf8mb4'onsite',_utf8mb4'phone',_utf8mb4'other'))),
  CONSTRAINT `ck_interview_sessions_reminder_minutes` CHECK (((`reminder_minutes` is null) or (`reminder_minutes` <= 10080))),
  CONSTRAINT `ck_interview_sessions_round_result` CHECK ((`round_result` in (_utf8mb4'pending',_utf8mb4'passed',_utf8mb4'rejected'))),
  CONSTRAINT `ck_interview_sessions_stage_context` CHECK ((((`stage_type` = _utf8mb4'interview') and (`round_no` >= 1)) or ((`stage_type` <> _utf8mb4'interview') and (`round_no` is null)))),
  CONSTRAINT `ck_interview_sessions_stage_type` CHECK ((`stage_type` in (_utf8mb4'interview',_utf8mb4'hr',_utf8mb4'offer',_utf8mb4'other'))),
  CONSTRAINT `ck_interview_sessions_status` CHECK ((`status` in (_utf8mb4'scheduled',_utf8mb4'completed',_utf8mb4'cancelled'))),
  CONSTRAINT `ck_interview_sessions_time_range` CHECK ((`end_at` > `start_at`))
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='排期与复盘共用的单场面试';
