','completed','pending','2026-08-31 14:30:00.000000','2026-08-31 15:30:00.000000','Asia/Shanghai','video',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-08-30 14:18:31.542968',NULL,NULL,2,'2026-08-30 14:18:27.678626','2026-08-30 14:18:31.542968'),(39,34,'08b9c6fe-293c-4ed2-8a34-c675a8d26465','other',NULL,'笔试','completed','pending','2026-09-08 06:44:00.000000','2026-09-08 08:14:00.000000','Asia/Shanghai','video','1111111111111111111111',NULL,NULL,NULL,NULL,NULL,'【虚构测试记录】\n\n本次笔试主要包含产品分析、需求拆解和数据判断三个部分。第一部分要求分析一款求职管理产品的新用户路径，我先从“岗位导入—简历投递—进度跟踪—面试复盘”四个关键动作拆解用户目标，并指出当前路径中可能出现的信息重复、状态不清晰和下一步入口不统一等问题。\n\n第二部分是一道产品方案题：假设用户同时管理二十个求职机会，需要设计一个更容易判断优先级的看板。我给出的方案包括按当前阶段分组、突出最近待办时间、为笔试和面试使用不同图标，并允许用户快速查看文字记录或录音。方案中还补充了空状态、完成状态、取消状态和移动端展示方式。\n\n第三部分是数据分析题。题目提供了虚构的投递、笔试、面试和 Offer 转化数据，需要判断主要流失环节。我先核对样本口径，再分别计算各阶段转化率，最后判断“收到笔试后未按时完成”是主要流失点。建议增加临近提醒、日历同步和超时标记，同时避免用单一转化率直接评价岗位质量。\n\n答题过程中有一处需求理解偏差：最初把“等待通知”和“筛选中”视为两个独立阶段，复查后发现两者对用户表达的含义接近，因此调整为只保留一个等待结果状态。整体答题约 82 分钟，剩余时间用于检查日期、链接和状态字段是否一致。\n\n自我复盘：结构化表达比较完整，能够说明方案取舍；不足是前两部分写得较多，数据题留出的检查时间偏少。后续可以先列提纲和时间预算，再开始详细作答。',NULL,NULL,'2026-09-01 07:07:21.772131',NULL,NULL,4,'2026-09-01 04:54:30.107559','2026-09-01 07:55:11.906024'),(40,34,'93a58056-784e-4a99-b4c3-917f20bf5e60','interview',1,'一面','completed','passed','2026-09-09 05:00:00.000000','2026-09-09 06:00:00.000000','Asia/Shanghai','video','测试链接',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-01 08:44:02.504335',NULL,NULL,3,'2026-09-01 08:22:21.674732','2026-09-01 10:03:53.000000');
/*!40000 ALTER TABLE `interview_sessions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `job_applications`
--

DROP TABLE IF EXISTS `job_applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_applications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '求职进程自增主键',
  `user_id` bigint unsigned NOT NULL COMMENT '求职进程所有者',
  `job_description_id` bigint unsigned DEFAULT NULL COMMENT '来源 JD，删除后解除引用',
  `resume_version_id` bigint unsigned DEFAULT NULL COMMENT '本次投递使用的不可变简历版本',
  `company_name_snapshot` varchar(200) NOT NULL COMMENT '建立进程时的公司名快照',
  `job_title_snapshot` varchar(200) NOT NULL COMMENT '建立进程时的岗位名快照',
  `job_snapshot` json NOT NULL COMMENT 'schema_version=1 的完整岗位业务快照',
  `resume_title_snapshot` varchar(255) DEFAULT NULL COMMENT '投递简历标题快照',
  `calendar_color` varchar(16) NOT NULL COMMENT 'Mac 日历语义颜色',
  `current_stage_type` varchar(24) NOT NULL COMMENT 'screening、interview、hr 或 offer',
  `current_round_no` smallint unsigned DEFAULT NULL COMMENT '普通面试轮次',
  `current_stage_label` varchar(100) NOT NULL COMMENT '筛选中、一面、二面、HR 面等',
  `stage_state` varchar(24) NOT NULL COMMENT '待安排、已排期、等待结果或协商中',
  `status` varchar(24) NOT NULL DEFAULT 'active' COMMENT 'active、rejected、withdrawn 或 closed',
  `offer_status` varchar(32) NOT NULL DEFAULT 'none' COMMENT 'OC、书面 Offer 与最终结果',
  `is_favorite` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否关注',
  `applied_at` datetime(6) DEFAULT NULL COMMENT '实际投递时间 UTC',
  `notes` text COMMENT '求职进程级备注',
  `archived_at` datetime(6) DEFAULT NULL COMMENT '归档时间 UTC',
  `lock_version` int unsigned NOT NULL DEFAULT '1' COMMENT '乐观锁版本',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间 UTC',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间 UTC',
  PRIMARY KEY (`id`),
  KEY `idx_job_applications_user_scope_updated` (`user_id`,`archived_at`,`status`,`updated_at` DESC,`id` DESC),
  KEY `idx_job_applications_user_stage` (`user_id`,`archived_at`,`status`,`current_stage_type`,`current_round_no`,`stage_state`),
  KEY `idx_job_applications_user_offer` (`user_id`,`archived_at`,`offer_status`),
  KEY `idx_job_applications_job_description` (`job_description_id`),
  KEY `idx_job_applications_resume_version` (`resume_version_id`),
  CONSTRAINT `fk_job_applications_job_description` FOREIGN KEY (`job_description_id`) REFERENCES `job_descriptions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_job_applications_resume_version` FOREIGN KEY (`resume_version_id`) REFERENCES `resume_versions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_job_applications_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_job_applications_calendar_color` CHECK ((`calendar_color` in (_utf8mb4'red',_utf8mb4'orange',_utf8mb4'yellow',_utf8mb4'green',_utf8mb4'blue',_utf8mb4'purple',_utf8mb4'gray'))),
  CONSTRAINT `ck_job_applications_is_favorite` CHECK ((`is_favorite` in (0,1))),
  CONSTRAINT `ck_job_applications_job_snapshot_object` CHECK ((json_type(`job_snapshot`) = _utf8mb4'OBJECT')),
  CONSTRAINT `ck_job_applications_lock_version` CHECK ((`lock_version` >= 1)),
  CONSTRAINT `ck_job_applications_offer_status` CHECK ((`offer_status` in (_utf8mb4'none',_utf8mb4'oc_received',_utf8mb4'written_offer_received',_utf8mb4'accepted',_utf8mb4'declined'))),
  CONSTRAINT `ck_job_applications_round_context` CHECK ((((`current_stage_type` = _utf8mb4'interview') and (`current_round_no` >= 1)) or ((`current_stage_type` <> _utf8mb4'interview') and (`current_round_no` is null)))),
  CONSTRAINT `ck_job_applications_snapshots_not_blank` CHECK (((length(trim(`company_name_snapshot`)) > 0) and (length(trim(`job_title_snapshot`)) > 0) and (length(trim(`current_stage_label`)) > 0))),
  CONSTRAINT `ck_job_applications_stage_state` CHECK ((`stage_state` in (_utf8mb4'awaiting_schedule',_utf8mb4'scheduled',_utf8mb4'awaiting_result',_utf8mb4'negotiating'))),
  CONSTRAINT `ck_job_applications_stage_type` CHECK ((`current_stage_type` in (_utf8mb4'screening',_utf8mb4'interview',_utf8mb4'hr',_utf8mb4'offer'))),
  CONSTRAINT `ck_job_applications_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'rejected',_utf8mb4'withdrawn',_utf8mb4'closed')))
