--
-- Table structure for table `job_descriptions`
--

DROP TABLE IF EXISTS `job_descriptions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_descriptions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'JD 自增主键',
  `user_id` bigint unsigned NOT NULL COMMENT 'JD 所有者',
  `job_title` varchar(200) NOT NULL COMMENT '岗位名称',
  `company_name` varchar(200) NOT NULL COMMENT '公司展示名称',
  `employment_type` varchar(24) DEFAULT NULL COMMENT '岗位类型',
  `description` longtext NOT NULL COMMENT '最终结构化 Markdown JD 正文',
  `skills` json NOT NULL COMMENT '去空去重后的技能字符串数组',
  `education_requirement` varchar(100) DEFAULT NULL COMMENT '学历要求',
  `experience_requirement` varchar(100) DEFAULT NULL COMMENT '经验或在校要求',
  `work_schedule` varchar(100) DEFAULT NULL COMMENT '工作或实习安排',
  `work_city` varchar(100) DEFAULT NULL COMMENT '工作城市或地区',
  `work_address` varchar(500) DEFAULT NULL COMMENT '详细工作地址',
  `work_mode` varchar(16) DEFAULT NULL COMMENT '工作方式',
  `salary_text` varchar(128) DEFAULT NULL COMMENT '薪资展示原文',
  `salary_min` decimal(12,2) DEFAULT NULL COMMENT '薪资区间下限',
  `salary_max` decimal(12,2) DEFAULT NULL COMMENT '薪资区间上限',
  `salary_currency` char(3) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'ISO 4217 币种',
  `salary_period` varchar(16) DEFAULT NULL COMMENT '计薪周期',
  `salary_months_per_year` smallint unsigned DEFAULT NULL COMMENT '年薪折算月数',
  `company_legal_name` varchar(255) DEFAULT NULL COMMENT '公司工商全称快照',
  `company_industry` varchar(100) DEFAULT NULL COMMENT '行业快照',
  `company_size` varchar(50) DEFAULT NULL COMMENT '公司规模快照',
  `company_financing_stage` varchar(50) DEFAULT NULL COMMENT '融资阶段快照',
  `company_description` longtext COMMENT '公司简介快照',
  `recruiter_name` varchar(100) DEFAULT NULL COMMENT '招聘者展示姓名',
  `recruiter_title` varchar(100) DEFAULT NULL COMMENT '招聘者职位',
  `source_type` varchar(24) NOT NULL COMMENT '来源类型：manual 或 external_import',
  `source_site` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '来源适配器标识',
  `source_job_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '来源站点原生岗位标识',
  `source_url` varchar(2048) DEFAULT NULL COMMENT '后端规范化来源链接',
  `source_url_hash` binary(32) DEFAULT NULL COMMENT '规范化来源链接 SHA-256',
  `imported_at` datetime(6) DEFAULT NULL COMMENT '外部结构化数据写入时间（UTC）',
  `notes` text COMMENT '用户个人备注',
  `lock_version` int unsigned NOT NULL DEFAULT '1' COMMENT '乐观锁版本',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（UTC）',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_descriptions_user_source_job` (`user_id`,`source_site`,`source_job_id`),
  UNIQUE KEY `uk_job_descriptions_user_source_url` (`user_id`,`source_url_hash`),
  KEY `idx_job_descriptions_user_updated_id` (`user_id`,`updated_at` DESC,`id` DESC),
  CONSTRAINT `fk_job_descriptions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_job_descriptions_company_name_not_blank` CHECK ((length(trim(`company_name`)) > 0)),
  CONSTRAINT `ck_job_descriptions_description_not_blank` CHECK ((length(trim(`description`)) > 0)),
  CONSTRAINT `ck_job_descriptions_employment_type` CHECK (((`employment_type` is null) or (`employment_type` in (_utf8mb4'full_time',_utf8mb4'part_time',_utf8mb4'internship',_utf8mb4'contract',_utf8mb4'temporary')))),
  CONSTRAINT `ck_job_descriptions_job_title_not_blank` CHECK ((length(trim(`job_title`)) > 0)),
  CONSTRAINT `ck_job_descriptions_lock_version` CHECK ((`lock_version` >= 1)),
  CONSTRAINT `ck_job_descriptions_salary_context` CHECK ((((`salary_min` is null) and (`salary_max` is null)) or ((`salary_currency` is not null) and (`salary_period` is not null)))),
  CONSTRAINT `ck_job_descriptions_salary_currency` CHECK (((`salary_currency` is null) or (length(`salary_currency`) = 3))),
  CONSTRAINT `ck_job_descriptions_salary_max` CHECK (((`salary_max` is null) or (`salary_max` >= 0))),
  CONSTRAINT `ck_job_descriptions_salary_min` CHECK (((`salary_min` is null) or (`salary_min` >= 0))),
  CONSTRAINT `ck_job_descriptions_salary_months` CHECK (((`salary_months_per_year` is null) or (`salary_months_per_year` >= 1))),
  CONSTRAINT `ck_job_descriptions_salary_period` CHECK (((`salary_period` is null) or (`salary_period` in (_utf8mb4'hour',_utf8mb4'day',_utf8mb4'month',_utf8mb4'year')))),
  CONSTRAINT `ck_job_descriptions_salary_range` CHECK (((`salary_min` is null) or (`salary_max` is null) or (`salary_max` >= `salary_min`))),
  CONSTRAINT `ck_job_descriptions_skills_array` CHECK ((json_type(`skills`) = _utf8mb4'ARRAY')),
  CONSTRAINT `ck_job_descriptions_source_fields` CHECK (((((`source_url` is null) and (`source_url_hash` is null) and (`source_site` is null) and (`source_job_id` is null)) or ((`source_url` is not null) and (`source_url_hash` is not null) and (`source_site` is not null))) and ((`source_job_id` is null) or (`source_site` is not null)) and (((`source_type` = _utf8mb4'external_import') and (`source_url` is not null) and (`source_site` is not null) and (`source_url_hash` is not null) and (`imported_at` is not null)) or ((`source_type` = _utf8mb4'manual') and (`imported_at` is null))))),
  CONSTRAINT `ck_job_descriptions_source_type` CHECK ((`source_type` in (_utf8mb4'manual',_utf8mb4'external_import'))),
  CONSTRAINT `ck_job_descriptions_work_mode` CHECK (((`work_mode` is null) or (`work_mode` in (_utf8mb4'onsite',_utf8mb4'hybrid',_utf8mb4'remote'))))
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户保存的结构化岗位描述';
/*!40101 SET character_set_client = @saved_cs_client */;

