--
-- Table structure for table `llm_call_logs`
--

DROP TABLE IF EXISTS `llm_call_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_call_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '调用日志主键',
  `call_id` varchar(40) NOT NULL COMMENT '逻辑调用唯一标识',
  `capability` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'chat' COMMENT '实际模型能力快照',
  `source` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'connection_test' COMMENT '稳定调用来源代码',
  `user_id` bigint unsigned NOT NULL COMMENT '发起调用的用户主键',
  `model_config_id` bigint unsigned DEFAULT NULL COMMENT '实际使用的模型配置主键，未选中模型时为空',
  `model_config_version` bigint unsigned DEFAULT NULL COMMENT '实际模型配置版本快照，未选中模型时为空',
  `model_name` varchar(128) DEFAULT NULL COMMENT '实际模型标识快照',
  `adapter` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '实际 LiteLLM adapter 快照',
  `model_call_name` varchar(128) DEFAULT NULL COMMENT '实际模型调用名快照',
  `status` varchar(16) NOT NULL DEFAULT 'pending' COMMENT '调用状态：pending（待处理）、succeeded（成功）、failed（失败）、cancelled（已取消）',
  `metering_status` varchar(16) NOT NULL DEFAULT 'unknown' COMMENT '计量状态：complete（完整）、partial（部分）、unknown（未知）',
  `input_tokens` bigint unsigned DEFAULT NULL COMMENT '输入令牌数量',
  `output_tokens` bigint unsigned DEFAULT NULL COMMENT '输出令牌数量',
  `input_price_per_million` decimal(18,8) DEFAULT NULL COMMENT '每百万输入令牌的美元价格快照',
  `output_price_per_million` decimal(18,8) DEFAULT NULL COMMENT '每百万输出令牌的美元价格快照',
  `estimated_cost` decimal(20,10) DEFAULT NULL COMMENT '预估调用成本（美元）',
  `latency_ms` bigint unsigned DEFAULT NULL COMMENT '调用耗时（毫秒）',
  `error_code` varchar(64) DEFAULT NULL COMMENT '非敏感稳定错误码',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '调用创建时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_llm_call_logs_call_id` (`call_id`),
  KEY `idx_llm_call_logs_created` (`created_at`,`id`),
  KEY `idx_llm_call_logs_user_created` (`user_id`,`created_at`,`id`),
  KEY `idx_llm_call_logs_model_created` (`model_config_id`,`created_at`,`id`),
  KEY `idx_llm_call_logs_status_created` (`status`,`created_at`,`id`),
  KEY `idx_llm_call_logs_model_source_created` (`model_config_id`,`source`,`created_at`,`id`),
  CONSTRAINT `fk_llm_call_logs_model_config_id_llm_model_configs` FOREIGN KEY (`model_config_id`) REFERENCES `llm_model_configs` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_llm_call_logs_user_id_users` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_llm_call_logs_adapter_pair` CHECK ((((`adapter` is null) and (`model_call_name` is null)) or ((`adapter` is not null) and (`model_call_name` is not null) and (length(trim(`adapter`)) > 0) and (length(trim(`model_call_name`)) > 0)))),
  CONSTRAINT `ck_llm_call_logs_estimated_cost_nonnegative` CHECK (((`estimated_cost` is null) or (`estimated_cost` >= 0))),
  CONSTRAINT `ck_llm_call_logs_input_price_nonnegative` CHECK (((`input_price_per_million` is null) or (`input_price_per_million` >= 0))),
  CONSTRAINT `ck_llm_call_logs_input_tokens_nonnegative` CHECK (((`input_tokens` is null) or (`input_tokens` >= 0))),
  CONSTRAINT `ck_llm_call_logs_latency_nonnegative` CHECK (((`latency_ms` is null) or (`latency_ms` >= 0))),
  CONSTRAINT `ck_llm_call_logs_metering_status` CHECK ((`metering_status` in (_utf8mb4'complete',_utf8mb4'partial',_utf8mb4'unknown'))),
  CONSTRAINT `ck_llm_call_logs_model_config_version` CHECK (((`model_config_version` is null) or (`model_config_version` >= 1))),
  CONSTRAINT `ck_llm_call_logs_output_price_nonnegative` CHECK (((`output_price_per_million` is null) or (`output_price_per_million` >= 0))),
  CONSTRAINT `ck_llm_call_logs_output_tokens_nonnegative` CHECK (((`output_tokens` is null) or (`output_tokens` >= 0))),
  CONSTRAINT `ck_llm_call_logs_source_not_blank` CHECK ((length(trim(`source`)) > 0)),
  CONSTRAINT `ck_llm_call_logs_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'succeeded',_utf8mb4'failed',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='大模型逻辑调用的状态、计量与成本快照';
/*!40101 SET character_set_client = @saved_cs_client */;

