DROP TABLE IF EXISTS `llm_capability_bindings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_capability_bindings` (
  `capability` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '系统模型能力标识',
  `model_config_id` bigint unsigned DEFAULT NULL COMMENT '当前候选模型配置主键，空表示未配置',
  `binding_version` bigint unsigned NOT NULL DEFAULT '1' COMMENT '能力绑定乐观锁版本',
  `validation_id` bigint unsigned DEFAULT NULL COMMENT '最近一次成功验证证据主键，存量 Chat 可为空',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（UTC）',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '最后更新时间（UTC）',
  PRIMARY KEY (`capability`),
  KEY `idx_llm_capability_bindings_model` (`model_config_id`,`capability`),
  KEY `fk_llm_capability_bindings_validation` (`validation_id`),
  CONSTRAINT `fk_llm_capability_bindings_model` FOREIGN KEY (`model_config_id`) REFERENCES `llm_model_configs` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_llm_capability_bindings_validation` FOREIGN KEY (`validation_id`) REFERENCES `llm_model_validations` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_llm_capability_bindings_capability` CHECK ((`capability` in (_utf8mb4'chat',_utf8mb4'resume_structuring',_utf8mb4'pi_agent',_utf8mb4'job_image_structuring'))),
  CONSTRAINT `ck_llm_capability_bindings_version` CHECK ((`binding_version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统模型能力到唯一当前候选的低基数绑定';
/*!40101 SET character_set_client = @saved_cs_client */;

