--
-- Table structure for table `llm_model_configs`
--

DROP TABLE IF EXISTS `llm_model_configs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_model_configs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '模型配置主键',
  `model_name` varchar(128) NOT NULL COMMENT 'LiteLLM 模型标识',
  `adapter` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'LiteLLM adapter 标识',
  `model_call_name` varchar(128) DEFAULT NULL COMMENT '不含 adapter 前缀的模型调用名',
  `api_base` varchar(512) DEFAULT NULL COMMENT '模型服务基础地址',
  `encrypted_api_key` text COMMENT '版本化加密凭据，禁止保存明文',
