DROP TABLE IF EXISTS `resume_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resume_versions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '版本快照自增主键',
  `resume_id` bigint unsigned NOT NULL COMMENT '所属简历',
  `version_no` int unsigned NOT NULL COMMENT '简历内单调递增版本号',
  `data_json` json NOT NULL COMMENT 'ResumeDocumentV1 内容快照',
  `style_json` json NOT NULL COMMENT 'ResumeStyleV1 样式快照',
  `reason` varchar(32) NOT NULL COMMENT '创建原因：initial、manual、before_restore 或 restore',
  `name` varchar(80) NOT NULL COMMENT '正式版本名称',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '快照创建时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_resume_versions_no` (`resume_id`,`version_no`),
  CONSTRAINT `fk_resume_versions_resume` FOREIGN KEY (`resume_id`) REFERENCES `resumes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_resume_versions_no` CHECK ((`version_no` >= 1)),
  CONSTRAINT `ck_resume_versions_reason` CHECK ((`reason` in (_utf8mb4'initial',_utf8mb4'manual',_utf8mb4'before_restore',_utf8mb4'restore',_utf8mb4'agent')))
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='不可变简历历史快照';
/*!40101 SET character_set_client = @saved_cs_client */;

