"custom_section_id\": \"blk_d2a84bdc1dd7cda82e0719a9\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_03\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Briefcase]: 工作经历\", \"semantic_kind\": \"work\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_ca4287a3fb03c6ffa64c98d3\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_04\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Award]: 项目经历\", \"semantic_kind\": \"project\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_f519c607114fa0d6de04205e\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_05\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Star]: 自我评价\", \"semantic_kind\": \"custom\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_4a2afb647756cf5fac869a4a\", \"semantic_confidence\": null}]}','{\"page\": {\"size\": \"A4\", \"margin_top_mm\": 0.0, \"margin_left_mm\": 10.0, \"margin_right_mm\": 10.0, \"margin_bottom_mm\": 8.0}, \"manifest\": {\"slots\": [{\"id\": \"avatar\", \"order\": 0, \"accepts\": [\"avatar\"], \"fallback\": false, \"required\": false, \"region_id\": \"main\"}, {\"id\": \"main-content\", \"order\": 0, \"accepts\": [\"basics\", \"profile\", \"work\", \"education\", \"project\", \"skills\", \"activity\", \"interests\", \"certificates\", \"awards\", \"languages\", \"custom\"], \"fallback\": true, \"required\": false, \"region_id\": \"main\"}], \"avatar\": {\"size\": 96, \"visibility\": \"show\", \"fallback_asset\": \"system-default\"}, \"regions\": [{\"id\": \"main\", \"kind\": \"main\", \"order\": 1}], \"renderer_key\": \"flow\"}, \"font_size\": 9.6, \"font_family\": \"source-han-serif\", \"line_height\": 1.4, \"accent_color\": \"#FF8A00\", \"template_key\": \"creative-orange-cn\", \"section_order\": [\"basics\", \"custom_sections\"], \"smart_one_page\": true}','initial','初始版本','2026-08-26 10:45:47.752036'),(2,2,1,'{\"basics\": {\"name\": \"张三\", \"email\": null, \"links\": [], \"phone\": null, \"photo\": null, \"summary\": null, \"headline\": null, \"location\": null}, \"sections\": {\"awards\": [], \"skills\": [], \"projects\": [], \"languages\": [], \"educations\": [], \"certificates\": [], \"custom_sections\": [{\"id\": \"blk_5b12b7a85c56867187488a77\", \"items\": [{\"id\": \"item_campus_professional_cn_00\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"![虚构头像](/templates/avatar-cat.jpg \\\"linkcv-avatar:82\\\")\\n\\n# 张三｜校招 / 社招通用简历\\n\\n13800000000 ｜ zhangsan@example.com ｜ 杭州\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"基本信息\"}, {\"id\": \"blk_356fcb7dbc9412c3487c64f2\", \"items\": [{\"id\": \"item_campus_professional_cn_01\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: meta\\n2020.09 - 2024.06\\n北辰财经大学\\n市场营销 · 本科\\nGPA 3.8 / 4.0\\n::::\\n\\n- **研究实践：** 参与区域消费趋势调研，负责问卷设计、数据清洗、交叉分析与结论汇报。\\n- **相关课程：** 市场营销、消费者行为、统计学、电子商务、数据可视化、商务写作。\\n- **校园荣誉：** 连续两年获专业奖学金，获校级优秀学生干部与创新实践奖。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"教育背景\"}, {\"id\": \"blk_b7514896532e7438dcea4f03\", \"items\": [{\"id\": \"item_campus_professional_cn_02\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: meta\\n2023.06 - 2023.09\\n星野零售科技有限公司\\n用户运营\\n运营实习生\\n::::\\n\\n- 维护商品信息与活动排期，协同设计、客服和供应链完成日常上线检查，周均跟进 80 余项任务。\\n- 分析访问、收藏与购买漏斗，提出页面信息层级和触达节奏优化建议，支持周度业务复盘。\\n- 参与年度主题活动策划，负责会场信息核验、用户引导、素材验收与效果数据整理。\\n- 建立活动问题清单与复盘模板，归纳高频异常和处理方案，减少后续活动重复沟通。\\n- 整理用户反馈并按场景归类，与产品共同推进 6 项体验问题修复和帮助文档更新。\\n\\n:::: meta\\n2022.07 - 2022.10\\n澄海内容科技有限公司\\n内容社区\\n运营实习生\\n::::\\n\\n- 完成内容审核、选题整理与用户互动，维护社区内容质量，日均处理内容 150 余条。\\n- 根据阅读完成率和互动数据调整发布节奏，沉淀可复用的选题清单与标题规范。\\n- 协助执行线上征集活动，跟踪报名、发布、奖品发放和复盘全流程。\\n- 维护创作者沟通群与常见问题库，提升活动通知触达和问题响应效率。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"实习经历\"}, {\"id\": \"blk_72414fd0f2217a5783ada57c\", \"items\": [{\"id\": \"item_campus_professional_cn_03\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: meta\\n2022.03 - 2022.11\\n北辰大学商学院\\n创新营销竞赛\\n团队负责人\\n::::\\n\\n- 组织五人团队完成需求拆解、市场调研、方案设计和现场答辩，制定周计划并跟进分工。\\n- 回收并清洗 520 份有效问卷，形成目标人群、使用场景与渠道偏好分析。\\n- 通过阶段评审和数据复盘迭代方案，最终获得校级一等奖。\\n- 负责答辩材料结构与演示设计，将研究过程转化为清晰的商业叙事。\\n\\n:::: meta\\n2021.03 - 2021.12\\n学生媒体中心\\n新媒体运营项目\\n项目成员\\n::::\\n\\n- 负责每周内容策划、排期和发布，持续优化标题、封面与互动方式。\\n- 建立月度数据看板，帮助团队识别高互动内容并调整栏目结构。\\n- 策划毕业季人物访谈专题，协调采访、编辑与发布，累计完成 12 篇原创内容。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"校园经历\"}, {\"id\": \"blk_27da3fb10ce20ef829ebf819\", \"items\": [{\"id\": \"item_campus_professional_cn_04\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"- **语言：** 英语六级，可阅读行业报告并撰写常用英文邮件。\\n- **工具：** Excel、PowerPoint、Photoshop、SPSS、XMind、Visio。\\n- **能力：** 数据清洗与基础分析、活动执行、用户调研、内容策划和跨团队协作。\\n- **证书：** 全国计算机等级考试二级、普通话水平测试二级甲等。\\n- **项目：** 可独立完成访谈提纲、问卷回收、基础统计和结论汇报。\\n- **实践：** 能够独立完成运营周报、活动复盘、竞品信息整理和基础数据看板。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"技能证书 / 其他\"}], \"work_experiences\": []}, \"semantic_sections\": [{\"id\": \"semantic_template_campus_professional_cn_00\", \"content_key\": \"custom_sections\", \"display_title\": \"基本信息\", \"semantic_kind\": \"basics\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_5b12b7a85c56867187488a77\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_01\", \"content_key\": \"custom_sections\", \"display_title\": \"教育背景\", \"semantic_kind\": \"education\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_356fcb7dbc9412c3487c64f2\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_02\", \"content_key\": \"custom_sections\", \"display_title\": \"实习经历\", \"semantic_kind\": \"work\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_b7514896532e7438dcea4f03\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_03\", \"content_key\": \"custom_sections\", \"display_title\": \"校园经历\", \"semantic_kind\": \"activity\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_72414fd0f2217a5783ada57c\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_04\", \"content_key\": \"custom_sections\", \"display_title\": \"技能证书 / 其他\", \"semantic_kind\": \"skills\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_27da3fb10ce20ef829ebf819\", \"semantic_confidence\": null}]}','{\"page\": {\"size\": \"A4\", \"margin_top_mm\": 8.0, \"margin_left_mm\": 9.0, \"margin_right_mm\": 9.0, \"margin_bottom_mm\": 8.0}, \"manifest\": {\"slots\": [{\"id\": \"avatar\", \"order\": 0, \"accepts\": [\"avatar\"], \"fallback\": false, \"required\": false, \"region_id\": \"main\"}, {\"id\": \"main-content\", \"order\": 0, \"accepts\": [\"basics\", \"profile\", \"work\", \"education\", \"project\", \"skills\", \"activity\", \"interests\", \"certificates\", \"awards\", \"languages\", \"custom\"], \"fallback\": true, \"required\": false, \"region_id\": \"main\"}], \"avatar\": {\"size\": 96, \"visibility\": \"show\", \"fallback_asset\": \"system-default\"}, \"regions\": [{\"id\": \"main\", \"kind\": \"main\", \"order\": 1}], \"renderer_key\": \"flow\"}, \"font_size\": 9.4, \"font_family\": \"source-han-serif\", \"line_height\": 1.38, \"accent_color\": \"#4F8DF7\", \"template_key\": \"campus-professional-cn\", \"section_order\": [\"basics\", \"custom_sections\"], \"smart_one_page\": true}','initial','初始版本','2026-08-26 11:36:43.356534'),(3,3,1,'{\"basics\": {\"name\": \"张三\", \"email\": null, \"links\": [], \"phone\": null, \"photo\": null, \"summary\": null, \"headline\": \"后端开发工程师\", \"location\": null}, \"sections\": {\"awards\": [], \"skills\": [], \"projects\": [], \"languages\": [], \"educations\": [], \"certificates\": [], \"custom_sections\": [], \"work_experiences\": []}, \"semantic_sections\": [{\"id\": \"semantic_basics\", \"content_key\": \"basics\", \"display_title\":