der\": 0, \"accepts\": [\"avatar\"], \"fallback\": false, \"required\": false, \"region_id\": \"main\"}, {\"id\": \"main-content\", \"order\": 0, \"accepts\": [\"basics\", \"profile\", \"work\", \"education\", \"project\", \"skills\", \"activity\", \"interests\", \"certificates\", \"awards\", \"languages\", \"custom\"], \"fallback\": true, \"required\": false, \"region_id\": \"main\"}], \"avatar\": {\"size\": 96, \"visibility\": \"hide\", \"fallback_asset\": \"none\"}, \"regions\": [{\"id\": \"main\", \"kind\": \"main\", \"order\": 1}], \"renderer_key\": \"flow\"}, \"font_size\": 14.0, \"font_family\": \"source-han-serif\", \"line_height\": 1.55, \"accent_color\": \"#2F4858\", \"template_key\": \"classic-cn\", \"section_order\": [\"basics\", \"work_experiences\", \"projects\", \"educations\", \"skills\"], \"smart_one_page\": false}','manual','后端岗位投递版','2026-08-29 18:20:25.187564');
