--
-- Table structure for table `resumes`
--

DROP TABLE IF EXISTS `resumes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resumes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '简历自增主键',
  `user_id` bigint unsigned NOT NULL COMMENT '简历所有者',
  `template_id` bigint unsigned DEFAULT NULL COMMENT '创建来源模板',
  `parse_task_id` bigint unsigned DEFAULT NULL COMMENT '来源解析任务标识，无数据库外键约束',
  `title` varchar(255) NOT NULL COMMENT '简历标题',
  `data_json` json NOT NULL COMMENT '当前 ResumeDocumentV1 内容',
  `style_json` json NOT NULL COMMENT '当前 ResumeStyleV1 样式',
  `lock_version` int unsigned NOT NULL DEFAULT '1' COMMENT '乐观锁版本',
  `source_type` varchar(16) NOT NULL DEFAULT 'blank' COMMENT '来源类型：blank、template 或 import',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（UTC）',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间（UTC）',
  `share_token` varchar(64) DEFAULT NULL COMMENT '分享链接 token，全局唯一，NULL 表示未分享',
  `share_visibility` varchar(16) DEFAULT NULL COMMENT '分享可见性：private 仅自己可见 / public 所有人可见',
  `share_expires_at` datetime(6) DEFAULT NULL COMMENT '分享过期时间（UTC），NULL 表示长期有效',
  `share_created_at` datetime(6) DEFAULT NULL COMMENT '分享创建时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_resumes_share_token` (`share_token`),
  UNIQUE KEY `uk_resumes_parse_task_id` (`parse_task_id`),
  KEY `idx_resumes_user_updated_id` (`user_id`,`updated_at` DESC,`id` DESC),
  KEY `idx_resumes_template_id` (`template_id`),
  CONSTRAINT `fk_resumes_template` FOREIGN KEY (`template_id`) REFERENCES `resume_templates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_resumes_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_resumes_lock_version` CHECK ((`lock_version` >= 1)),
  CONSTRAINT `ck_resumes_share_fields` CHECK ((((`share_token` is null) and (`share_visibility` is null) and (`share_created_at` is null)) or ((`share_token` is not null) and (`share_visibility` is not null) and (`share_created_at` is not null)))),
  CONSTRAINT `ck_resumes_share_visibility` CHECK (((`share_visibility` is null) or (`share_visibility` in (_utf8mb4'private',_utf8mb4'public')))),
  CONSTRAINT `ck_resumes_source_type` CHECK ((`source_type` in (_utf8mb4'blank',_utf8mb4'template',_utf8mb4'import'))),
  CONSTRAINT `ck_resumes_title_not_blank` CHECK ((char_length(trim(`title`)) > 0))
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户简历当前版本';
/*!40101 SET character_set_client = @saved_cs_client */;

