INSERT INTO `resumes` VALUES (1,1,9,NULL,'测试1','{\"basics\": {\"name\": \"张三\", \"email\": null, \"links\": [], \"phone\": null, \"photo\": null, \"summary\": null, \"headline\": null, \"location\": null}, \"sections\": {\"awards\": [], \"skills\": [], \"projects\": [], \"languages\": [], \"educations\": [], \"certificates\": [], \"custom_sections\": [{\"id\": \"blk_95b79ce238d9e5f50cc99349\", \"items\": [{\"id\": \"item_creative_orange_cn_00\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"![虚构头像](/templates/avatar-cat.jpg \\\"linkcv-avatar:112\\\")\\n\\n# 张三｜UI 设计师\\n\\n:icon[MapPin]: 浙江杭州 ｜ :icon[Mail]: zhangsan@example.com ｜ 2024 届\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"基本信息\"}, {\"id\": \"blk_36f3db36def02c1ef7ba3982\", \"items\": [{\"id\": \"item_creative_orange_cn_01\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"::: left\\n**海岚艺术大学**　视觉传达设计（硕士）　GPA 3.8 / 4.0\\n:::\\n\\n::: right\\n2021.09 - 2024.06\\n:::\\n\\n::: left\\n**南山商学院**　数字媒体艺术（学士）　GPA 3.7 / 4.0\\n:::\\n\\n::: right\\n2017.09 - 2021.06\\n:::\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \":icon[GraduationCap]: 教育经历\"}, {\"id\": \"blk_d2a84bdc1dd7cda82e0719a9\", \"items\": [{\"id\": \"item_creative_orange_cn_02\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: trio\\n**技能名称：** Photoshop\\n**使用时长：** 5 年\\n**熟练程度：** 精通\\n::::\\n\\n:::: trio\\n**技能名称：** Figma\\n**使用时长：** 4 年\\n**熟练程度：** 熟练\\n::::\\n\\n:::: trio\\n**技能名称：** After Effects\\n**使用时长：** 3 年\\n**熟练程度：** 熟练\\n::::\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \":icon[Code2]: 个人技能\"}, {\"id\": \"blk_ca4287a3fb03c6ffa64c98d3\", \"items\": [{\"id\": \"item_creative_orange_cn_03\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"::: left\\n**知见数字科技有限公司｜UI 设计师｜杭州**\\n:::\\n\\n::: right\\n2023.07 - 至今\\n:::\\n\\n1. 负责电商平台首页、专题活动和关键交易页面的视觉设计与迭代，覆盖桌面端与移动端。\\n2. 建立商品素材规范与组件模板，统一布局、字体、色彩和状态表达，提高常用页面交付效率。\\n3. 完成图片精修、信息排版和多尺寸推广素材适配，确保线上视觉一致性。\\n4. 与产品、研发和运营协作，根据转化数据、客服反馈与可用性问题持续优化方案。\\n5. 梳理设计验收清单并跟进上线还原，对间距、交互状态和异常场景进行逐项核对。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \":icon[Briefcase]: 工作经历\"}, {\"id\": \"blk_f519c607114fa0d6de04205e\", \"items\": [{\"id\": \"item_creative_orange_cn_04\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"**星图商家工作台**\\n\\n- **项目简介：** 面向零售商家的经营管理平台，覆盖商品、订单、会员和经营分析。\\n- **工作内容：**\\n  1. 访谈店长与门店员工，梳理角色权限、高频任务与信息查找路径。\\n  2. 设计桌面端信息架构和关键操作流程，补齐加载、空状态、错误与权限提示。\\n  3. 建立表格、筛选器、数据卡片和图表组件规范，统一交互状态与视觉层级。\\n  4. 与前端共同核对组件边界和响应式规则，跟进设计验收与上线复盘。\\n\\n**拾光城市文化活动小程序**\\n\\n- **项目简介：** 为城市展览与公共活动提供发现、预约、入场和收藏服务。\\n- **工作内容：**\\n  1. 负责用户旅程、线框图和高保真视觉，统一活动卡片与场馆信息结构。\\n  2. 设计预约冲突、名额不足和取消退款等关键反馈，降低用户理解成本。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \":icon[Award]: 项目经历\"}, {\"id\": \"blk_4a2afb647756cf5fac869a4a\", \"items\": [{\"id\": \"item_creative_orange_cn_05\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"热爱视觉与交互设计，能够从业务目标和用户任务出发组织信息；重视设计规范、无障碍细节、交付质量与团队协作，善于通过用户反馈、可用性观察和业务数据持续迭代。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \":icon[Star]: 自我评价\"}], \"work_experiences\": []}, \"semantic_sections\": [{\"id\": \"semantic_template_creative_orange_cn_00\", \"content_key\": \"custom_sections\", \"display_title\": \"基本信息\", \"semantic_kind\": \"basics\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_95b79ce238d9e5f50cc99349\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_01\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[GraduationCap]: 教育经历\", \"semantic_kind\": \"education\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_36f3db36def02c1ef7ba3982\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_02\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Code2]: 个人技能\", \"semantic_kind\": \"skills\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_d2a84bdc1dd7cda82e0719a9\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_03\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Briefcase]: 工作经历\", \"semantic_kind\": \"work\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_ca4287a3fb03c6ffa64c98d3\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_04\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Award]: 项目经历\", \"semantic_kind\": \"project\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_f519c607114fa0d6de04205e\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_creative_orange_cn_05\", \"content_key\": \"custom_sections\", \"display_title\": \":icon[Star]: 自我评价\", \"semantic_kind\": \"custom\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_4a2afb647756cf5fac869a4a\", \"semantic_confidence\": null}]}','{\"page\": {\"size\": \"A4\", \"margin_top_mm\": 0.0, \"margin_left_mm\": 10.0, \"margin_right_mm\": 10.0, \"margin_bottom_mm\": 8.0}, \"manifest\": {\"slots\": [{\"id\": \"avatar\", \"order\": 0, \"accepts\": [\"avatar\"], \"fallback\": false, \"required\": false, \"region_id\": \"main\"}, {\"id\": \"main-content\", \"order\": 0, \"accepts\": [\"basics\", \"profile\", \"work\", \"education\", \"project\", \"skills\", \"activity\", \"interests\", \"certificates\", \"awards\", \"languages\", \"custom\"], \"fallback\": true, \"required\": false, \"region_id\": \"main\"}], \"avatar\": {\"size\": 96, \"visibility\": \"show\", \"fallback_asset\": \"system-default\"}, \"regions\": [{\"id\": \"main\", \"kind\": \"main\", \"order\": 1}], \"renderer_key\": \"flow\"}, \"font_size\": 9.6, \"font_family\": \"source-han-serif\", \"line_height\": 1.4, \"accent_color\": \"#FF8A00\", \"template_key\": \"creative-orange-cn\", \"section_order\": [\"basics\", \"custom_sections\"], \"smart_one_page\": true}',1,'template','2026-08-26 10:45:47.747264','2026-08-26 10:45:47.747264',NULL,NULL,NULL,NULL),(2,1,7,NULL,'11111','{\"basics\": {\"name\": \"张三\", \"email\": null, \"links\": [], \"phone\": null, \"photo\": null, \"summary\": null, \"headline\": null, \"location\": null}, \"sections\": {\"awards\": [], \"skills\": [], \"projects\": [], \"languages\": [], \"educations\": [], \"certificates\": [], \"custom_sections\": [{\"id\": \"blk_5b12b7a85c56867187488a77\", \"items\": [{\"id\": \"item_campus_professional_cn_00\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"![虚构头像](/templates/avatar-cat.jpg \\\"linkcv-avatar:82\\\")\\n\\n# 张三｜校招 / 社招通用简历\\n\\n13800000000 ｜ zhangsan@example.com ｜ 杭州\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"基本信息\"}, {\"id\": \"blk_356fcb7dbc9412c3487c64f2\", \"items\": [{\"id\": \"item_campus_professional_cn_01\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: meta\\n2020.09 - 2024.06\\n北辰财经大学\\n市场营销 · 本科\\nGPA 3.8 / 4.0\\n::::\\n\\n- **研究实践：** 参与区域消费趋势调研，负责问卷设计、数据清洗、交叉分析与结论汇报。\\n- **相关课程：** 市场营销、消费者行为、统计学、电子商务、数据可视化、商务写作。\\n- **校园荣誉：** 连续两年获专业奖学金，获校级优秀学生干部与创新实践奖。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"教育背景\"}, {\"id\": \"blk_b7514896532e7438dcea4f03\", \"items\": [{\"id\": \"item_campus_professional_cn_02\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: meta\\n2023.06 - 2023.09\\n星野零售科技有限公司\\n用户运营\\n运营实习生\\n::::\\n\\n- 维护商品信息与活动排期，协同设计、客服和供应链完成日常上线检查，周均跟进 80 余项任务。\\n- 分析访问、收藏与购买漏斗，提出页面信息层级和触达节奏优化建议，支持周度业务复盘。\\n- 参与年度主题活动策划，负责会场信息核验、用户引导、素材验收与效果数据整理。\\n- 建立活动问题清单与复盘模板，归纳高频异常和处理方案，减少后续活动重复沟通。\\n- 整理用户反馈并按场景归类，与产品共同推进 6 项体验问题修复和帮助文档更新。\\n\\n:::: meta\\n2022.07 - 2022.10\\n澄海内容科技有限公司\\n内容社区\\n运营实习生\\n::::\\n\\n- 完成内容审核、选题整理与用户互动，维护社区内容质量，日均处理内容 150 余条。\\n- 根据阅读完成率和互动数据调整发布节奏，沉淀可复用的选题清单与标题规范。\\n- 协助执行线上征集活动，跟踪报名、发布、奖品发放和复盘全流程。\\n- 维护创作者沟通群与常见问题库，提升活动通知触达和问题响应效率。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"实习经历\"}, {\"id\": \"blk_72414fd0f2217a5783ada57c\", \"items\": [{\"id\": \"item_campus_professional_cn_03\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \":::: meta\\n2022.03 - 2022.11\\n北辰大学商学院\\n创新营销竞赛\\n团队负责人\\n::::\\n\\n- 组织五人团队完成需求拆解、市场调研、方案设计和现场答辩，制定周计划并跟进分工。\\n- 回收并清洗 520 份有效问卷，形成目标人群、使用场景与渠道偏好分析。\\n- 通过阶段评审和数据复盘迭代方案，最终获得校级一等奖。\\n- 负责答辩材料结构与演示设计，将研究过程转化为清晰的商业叙事。\\n\\n:::: meta\\n2021.03 - 2021.12\\n学生媒体中心\\n新媒体运营项目\\n项目成员\\n::::\\n\\n- 负责每周内容策划、排期和发布，持续优化标题、封面与互动方式。\\n- 建立月度数据看板，帮助团队识别高互动内容并调整栏目结构。\\n- 策划毕业季人物访谈专题，协调采访、编辑与发布，累计完成 12 篇原创内容。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"校园经历\"}, {\"id\": \"blk_27da3fb10ce20ef829ebf819\", \"items\": [{\"id\": \"item_campus_professional_cn_04\", \"title\": null, \"content\": {\"format\": \"markdown\", \"content\": \"- **语言：** 英语六级，可阅读行业报告并撰写常用英文邮件。\\n- **工具：** Excel、PowerPoint、Photoshop、SPSS、XMind、Visio。\\n- **能力：** 数据清洗与基础分析、活动执行、用户调研、内容策划和跨团队协作。\\n- **证书：** 全国计算机等级考试二级、普通话水平测试二级甲等。\\n- **项目：** 可独立完成访谈提纲、问卷回收、基础统计和结论汇报。\\n- **实践：** 能够独立完成运营周报、活动复盘、竞品信息整理和基础数据看板。\"}, \"subtitle\": null, \"source_refs\": []}], \"title\": \"技能证书 / 其他\"}], \"work_experiences\": []}, \"semantic_sections\": [{\"id\": \"semantic_template_campus_professional_cn_00\", \"content_key\": \"custom_sections\", \"display_title\": \"基本信息\", \"semantic_kind\": \"basics\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_5b12b7a85c56867187488a77\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_01\", \"content_key\": \"custom_sections\", \"display_title\": \"教育背景\", \"semantic_kind\": \"education\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_356fcb7dbc9412c3487c64f2\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_02\", \"content_key\": \"custom_sections\", \"display_title\": \"实习经历\", \"semantic_kind\": \"work\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_b7514896532e7438dcea4f03\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_03\", \"content_key\": \"custom_sections\", \"display_title\": \"校园经历\", \"semantic_kind\": \"activity\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_72414fd0f2217a5783ada57c\", \"semantic_confidence\": null}, {\"id\": \"semantic_template_campus_professional_cn_04\", \"content_key\": \"custom_sections\", \"display_title\": \"技能证书 / 其他\", \"semantic_kind\": \"skills\", \"semantic_source\": \"system\", \"custom_section_id\": \"blk_27da3fb10ce20ef829ebf819\", \"semantic_confidence\": null}]}','{\"page\": {\"size\": \"A4\", \"margin_top_mm\": 8.0, \"margin_left_mm\": 9.0, \"margin_right_mm\": 9.0, \"margin_bottom_mm\": 8.0}, \"manifest\": {\"slots\": [{\"id\": \"avatar\", \"order\": 0, \"accepts\": [\"avatar\"], \"fallback\": false, \"required\": false, \"region_id\": \"main\"}, {\"id\": \"main-content\", \"order\": 0, \"accepts\": [\"basics\", \"profile\", \"work\", \"education\", \"project\", \"skills\", \"activity\", \"interests\", \"certificates\", \"awards\", \"languages\", \"custom\"], \"fallback\": true, \"required\": false, \"region_id\": \"main\"}], \"avatar\": {\"size\": 96, \"visibility\": \"show\", \"fallback_asset\": \"system-default\"}, \"regions\": [{\"id\": \"main\", \"kind\": \"main\", \"order\": 1}], \"renderer_key\": \"flow\"}, \"font_size\": 9.4, \"font_family\": \"source-han-serif\", \"line_height\": 1.38, \"accent_color\": \"#4F8DF7\", \"template_key\": \"campus-professional-cn\", \"section_order\": [\"basics\", \"custom_sections\"], \"smart_one_page\": true}',1,'template','2026-08-26 11:36:43.352699','2026-08-26 11:36:43.352699',NULL,NULL,NULL,NULL),(3,3,NULL,NULL,'求职流程测试简历（虚构）','{\"basics\": {\"name\": \"张三\", \"email\": null, \"links\": [], \"phone\": null, \"photo\": null, \"summary\": null, \"headline\": \"后端开发工程师\", \"location\": null}, \"sections\": {\"awards\": [], \"skills\": [], \"projects\": [], \"languages\": [], \"educations\": [], \"certificates\": [], \"custom_sections\": [], \"work_experiences\": []}, \"semantic_sections\": [{\"id\": \"semantic_basics\", \"content_key\": \"basics\", \"display_title\": \"基本信息\", \"semantic_kind\": \"basics\", \"semantic_source\": \"system\", \"custom_section_id\": null, \"semantic_confidence\": null}]}','{\"page\": {\"size\": \"A4\", \"margin_top_mm\": 14.0, \"margin_left_mm\": 16.0, \"margin_right_mm\": 16.0, \"margin_bottom_mm\": 14.0}, \"manifest\": {\"slots\": [{\"id\": \"avatar\", \"order\": 0, \"accepts\": [\"avatar\"], \"fallback\": false, \"required\": false, \"region_id\": \"main\"}, {\"id\": \"main-content\", \"order\": 0, \"accepts\": [\"basics\", \"profile\", \"work\", \"education\", \"project\", \"skills\", \"activity\", \"interests\", \"certificates\", \"awards\", \"languages\", \"custom\"], \"fallback\": true, \"required\": false, \"region_id\": \"main\"}], \"avatar\": {\"size\": 96, \"visibility\": \"hide\", \"fallback_asset\": \"none\"}, \"regions\": [{\"id\": \"main\", \"kind\": \"main\", \"order\": 1}], \"renderer_key\": \"flow\"}, \"font_size\": 14.0, \"font_family\": \"source-han-serif\", \"line_height\": 1.55, \"accent_color\": \"#2F4858\", \"template_key\": \"classic-cn\", \"section_order\": [\"basics\", \"work_experiences\", \"projects\", \"educations\", \"skills\"], \"smart_one_page\": false}',1,'blank','2026-08-29 18:20:25.140662','2026-08-29 18:20:25.140662',NULL,NULL,NULL,NULL);
