--
-- Table structure for table `user_dataset`
--

DROP TABLE IF EXISTS `user_dataset`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_dataset` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '数据集自增主键',
  `user_id` bigint unsigned NOT NULL COMMENT '所属用户 ID',
  `idempotency_key` varchar(64) NOT NULL COMMENT '用户范围内上传幂等键',
  `request_fingerprint` char(64) NOT NULL COMMENT '规范化文件名、检测格式、大小和 SHA-256 的请求指纹',
  `parse_task_id` bigint unsigned DEFAULT NULL COMMENT '关联的解析任务标识，无数据库外键约束',
  `file_name` varchar(255) NOT NULL COMMENT '原始上传文件名（已安全化）',
  `file_format` varchar(10) NOT NULL COMMENT '文件格式：docx/pdf/md/txt',
  `content_type` varchar(128) NOT NULL COMMENT '服务端规范化内容类型',
  `file_size` bigint unsigned NOT NULL COMMENT '文件大小（字节）',
  `object_name` varchar(512) NOT NULL COMMENT '对象存储对象键',
  `sha256` char(64) NOT NULL COMMENT '文件内容 SHA-256 十六进制摘要',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_dataset_object_name` (`object_name`),
  UNIQUE KEY `uk_user_dataset_user_idempotency` (`user_id`,`idempotency_key`),
  UNIQUE KEY `uk_user_dataset_parse_task_id` (`parse_task_id`),
  KEY `idx_user_dataset_user_created` (`user_id`,`created_at` DESC),
  CONSTRAINT `fk_user_dataset_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_user_dataset_file_format` CHECK ((`file_format` in (_utf8mb4'docx',_utf8mb4'pdf',_utf8mb4'md',_utf8mb4'txt')))
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户知识库数据集';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user_dataset`
--

