DROP TABLE IF EXISTS `user_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_profiles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '画像自增主键',
  `user_id` bigint unsigned NOT NULL COMMENT '画像所有者用户 id',
  `lock_version` int unsigned NOT NULL COMMENT '乐观锁版本，写请求必须携带上次读取值',
  `salary_min` decimal(12,2) DEFAULT NULL COMMENT '期望薪资下限',
  `salary_max` decimal(12,2) DEFAULT NULL COMMENT '期望薪资上限',
  `salary_currency` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '期望薪资币种 ISO 4217',
  `salary_period` varchar(16) DEFAULT NULL COMMENT '计薪周期：hour/day/month/year',
  `school` varchar(255) DEFAULT NULL COMMENT '学校名称',
  `school_tier` json NOT NULL COMMENT '学校层级字符串数组：project_985/project_211/double_first_class',
  `major` varchar(100) DEFAULT NULL COMMENT '专业方向',
  `education_level` varchar(24) DEFAULT NULL COMMENT '学历层次：high_school/junior_college/bachelor/master/doctor',
  `years_experience` int unsigned DEFAULT NULL COMMENT '工作年限（应届生填 0）',
  `languages` json NOT NULL COMMENT '语言能力字符串数组',
  `skills` json NOT NULL COMMENT '技能字符串数组',
  `certifications` json NOT NULL COMMENT '证书字符串数组',
  `honors` json NOT NULL COMMENT '个人荣誉字符串数组',
  `campus_experiences` json NOT NULL COMMENT '校园经历字符串数组',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（UTC）',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间（UTC）',
  `candidate_cities` json NOT NULL COMMENT '可接受工作城市字符串数组',
  `employment_types` json NOT NULL COMMENT '可接受工作性质数组：full_time/part_time/internship/contract/temporary',
  `candidate_status` varchar(24) DEFAULT NULL COMMENT '候选人类型：fresh_graduate/experienced',
  `graduation_year` smallint unsigned DEFAULT NULL COMMENT '应届生毕业年份，candidate_status=fresh_graduate 时必填',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_profiles_user_id` (`user_id`),
  KEY `idx_user_profiles_user_updated` (`user_id`,`updated_at` DESC,`id` DESC),
  CONSTRAINT `fk_user_profiles_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_user_profiles_campus_experiences_array` CHECK ((lower(json_type(`campus_experiences`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_candidate_cities_array` CHECK ((lower(json_type(`candidate_cities`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_candidate_experience_context` CHECK ((((`candidate_status` is null) and (`graduation_year` is null)) or ((`candidate_status` is not null) and (`candidate_status` = _utf8mb4'fresh_graduate') and (`graduation_year` is not null) and (`years_experience` is not null) and (`years_experience` = 0)) or ((`candidate_status` is not null) and (`candidate_status` = _utf8mb4'experienced') and (`graduation_year` is null)))),
  CONSTRAINT `ck_user_profiles_candidate_status` CHECK (((`candidate_status` is null) or (`candidate_status` in (_utf8mb4'fresh_graduate',_utf8mb4'experienced')))),
  CONSTRAINT `ck_user_profiles_certifications_array` CHECK ((lower(json_type(`certifications`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_education_level` CHECK (((`education_level` is null) or (`education_level` in (_utf8mb4'high_school',_utf8mb4'junior_college',_utf8mb4'bachelor',_utf8mb4'master',_utf8mb4'doctor')))),
  CONSTRAINT `ck_user_profiles_employment_types_array` CHECK ((lower(json_type(`employment_types`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_graduation_year` CHECK (((`graduation_year` is null) or (`graduation_year` between 1900 and 9999))),
  CONSTRAINT `ck_user_profiles_honors_array` CHECK ((lower(json_type(`honors`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_languages_array` CHECK ((lower(json_type(`languages`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_lock_version` CHECK ((`lock_version` >= 1)),
  CONSTRAINT `ck_user_profiles_salary_context` CHECK ((((`salary_min` is null) and (`salary_max` is null)) or ((`salary_currency` is not null) and (`salary_period` is not null)))),
  CONSTRAINT `ck_user_profiles_salary_currency` CHECK (((`salary_currency` is null) or (length(`salary_currency`) = 3))),
  CONSTRAINT `ck_user_profiles_salary_period` CHECK (((`salary_period` is null) or (`salary_period` in (_utf8mb4'hour',_utf8mb4'day',_utf8mb4'month',_utf8mb4'year')))),
  CONSTRAINT `ck_user_profiles_salary_range` CHECK (((`salary_min` is null) or (`salary_max` is null) or (`salary_max` >= `salary_min`))),
  CONSTRAINT `ck_user_profiles_school_tier_array` CHECK ((lower(json_type(`school_tier`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_skills_array` CHECK ((lower(json_type(`skills`)) = _utf8mb4'array')),
  CONSTRAINT `ck_user_profiles_years_experience` CHECK (((`years_experience` is null) or (`years_experience` >= 0)))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户个人画像';
/*!40101 SET character_set_client = @saved_cs_client */;

