DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '用户自增主键',
  `email` varchar(254) DEFAULT NULL COMMENT '规范化后的登录邮箱（微信登录用户可为空）',
  `password_hash` varchar(255) DEFAULT NULL COMMENT '密码摘要，不保存明文（微信登录用户可为空）',
  `nickname` varchar(50) NOT NULL COMMENT '用户展示昵称',
  `avatar_object_key` varchar(512) DEFAULT NULL COMMENT '私有头像对象键',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '账号状态：0 禁用，1 启用',
  `is_admin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '管理员标记：0 否，1 是',
  `last_login_at` datetime(6) DEFAULT NULL COMMENT '最近一次成功登录时间（UTC）',
  `wechat_openid` varchar(64) DEFAULT NULL COMMENT '微信小程序 openid，绑定后写入，全局唯一',
  `wechat_bound_at` datetime(6) DEFAULT NULL COMMENT '微信绑定时间（UTC）',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间（UTC）',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_email` (`email`),
  UNIQUE KEY `uk_users_wechat_openid` (`wechat_openid`),
  CONSTRAINT `ck_users_is_admin` CHECK ((`is_admin` in (0,1))),
  CONSTRAINT `ck_users_status` CHECK ((`status` in (0,1)))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户账号';
